//! `Array[T]` objects: a growable buffer of elements described by a [`TypeInfo`].

use crate::TypeInfo;
use crate::string::LoomString;
use std::alloc::{Layout, alloc, dealloc, realloc};

/// The heap object behind a Loom `Array[T]`.
#[derive(Debug)]
pub struct LoomArray {
    /// The element descriptor.
    pub info: *const TypeInfo,
    data: *mut u8,
    capacity: usize,
    /// The number of elements.
    pub len: usize,
}

impl LoomArray {
    fn info(&self) -> &TypeInfo {
        // SAFETY: descriptors are static data generated by the code generator.
        unsafe { &*self.info }
    }

    fn stride(&self) -> usize {
        let info = self.info();
        info.size.max(1).next_multiple_of(info.align.max(1))
    }

    fn layout(&self, capacity: usize) -> Layout {
        Layout::from_size_align(self.stride() * capacity.max(1), self.info().align.max(1))
            .unwrap_or(Layout::new::<u8>())
    }

    /// A pointer to element `index` (which must be in bounds).
    ///
    /// # Safety
    ///
    /// `index` must be less than the capacity.
    #[must_use]
    pub unsafe fn element(&self, index: usize) -> *mut u8 {
        // SAFETY: the caller keeps `index` within the allocation.
        unsafe { self.data.add(index * self.stride()) }
    }

    fn reserve_one(&mut self) {
        if self.len < self.capacity {
            return;
        }
        let new_capacity = (self.capacity * 2).max(4);
        let new_layout = self.layout(new_capacity);
        let data = if self.data.is_null() {
            // SAFETY: the layout has a non-zero size.
            unsafe { alloc(new_layout) }
        } else {
            // SAFETY: `data` was allocated with `self.layout(self.capacity)`.
            unsafe { realloc(self.data, self.layout(self.capacity), new_layout.size()) }
        };
        if data.is_null() {
            std::alloc::handle_alloc_error(new_layout);
        }
        self.data = data;
        self.capacity = new_capacity;
    }
}

/// Borrows the array behind a handle.
///
/// # Safety
///
/// `a` must be a live array handle with no other active mutable borrow.
unsafe fn get<'a>(a: *mut LoomArray) -> &'a mut LoomArray {
    // SAFETY: the caller guarantees a live, unaliased handle.
    unsafe { &mut *a }
}

fn index_panic(
    index: i64,
    length: usize,
    file: *const u8,
    file_len: usize,
    line: u32,
    column: u32,
) -> ! {
    // SAFETY: the code generator passes valid UTF-8 for the file name.
    let file = unsafe { crate::str_from(file, file_len) };
    crate::panic_at(
        &format!("index out of bounds: the length is {length} but the index is {index}"),
        file,
        line,
        column,
    )
}

/// A new empty array of elements described by `info`.
#[unsafe(no_mangle)]
pub extern "C" fn loom_array_new(info: *const TypeInfo) -> *mut LoomArray {
    Box::into_raw(Box::new(LoomArray {
        info,
        data: std::ptr::null_mut(),
        capacity: 0,
        len: 0,
    }))
}

/// The number of elements.
///
/// # Safety
///
/// `a` must be a live array.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_len(a: *mut LoomArray) -> i64 {
    // SAFETY: `a` is live.
    i64::try_from(unsafe { get(a) }.len).unwrap_or(i64::MAX)
}

/// A pointer to element `index`; panics if it is out of bounds.
///
/// # Safety
///
/// `a` must be a live array; the file pointer must be valid UTF-8.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_get(
    a: *mut LoomArray,
    index: i64,
    file: *const u8,
    file_len: usize,
    line: u32,
    column: u32,
) -> *mut u8 {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    match usize::try_from(index) {
        // SAFETY: `i` is in bounds.
        Ok(i) if i < array.len => unsafe { array.element(i) },
        _ => index_panic(index, array.len, file, file_len, line, column),
    }
}

/// Appends the element at `src`, which is moved in.
///
/// # Safety
///
/// `a` must be live and `src` must point to a value of the element type.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_push(a: *mut LoomArray, src: *const u8) {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    array.reserve_one();
    let size = array.info().size;
    // SAFETY: there is room for one more element, and `src` holds `size` bytes.
    unsafe { std::ptr::copy_nonoverlapping(src, array.element(array.len), size) };
    array.len += 1;
}

/// Moves the last element to `dst`; returns 0 if the array is empty.
///
/// # Safety
///
/// `a` must be live and `dst` must have room for an element.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_pop(a: *mut LoomArray, dst: *mut u8) -> u8 {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    if array.len == 0 {
        return 0;
    }
    array.len -= 1;
    let size = array.info().size;
    // SAFETY: the element at `len` is initialized and now owned by `dst`.
    unsafe { std::ptr::copy_nonoverlapping(array.element(array.len), dst, size) };
    1
}

/// Inserts the element at `src` before `index`; panics if `index > length`.
///
/// # Safety
///
/// `a` must be live, `src` must hold an element, and the file pointer must be valid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_insert(
    a: *mut LoomArray,
    index: i64,
    src: *const u8,
    file: *const u8,
    file_len: usize,
    line: u32,
    column: u32,
) {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let Some(i) = usize::try_from(index).ok().filter(|&i| i <= array.len) else {
        // SAFETY: forwarded.
        let file = unsafe { crate::str_from(file, file_len) };
        crate::panic_at(
            &format!(
                "insertion index {index} is out of bounds for length {}",
                array.len
            ),
            file,
            line,
            column,
        );
    };
    array.reserve_one();
    let stride = array.stride();
    let size = array.info().size;
    // SAFETY: there is room for one more element; the tail is shifted within the buffer.
    unsafe {
        std::ptr::copy(
            array.element(i),
            array.element(i + 1),
            (array.len - i) * stride,
        );
        std::ptr::copy_nonoverlapping(src, array.element(i), size);
    }
    array.len += 1;
}

/// Moves element `index` to `dst`, shifting later elements; panics if out of bounds.
///
/// # Safety
///
/// `a` must be live, `dst` must have room for an element, and the file pointer must be valid.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_remove(
    a: *mut LoomArray,
    index: i64,
    dst: *mut u8,
    file: *const u8,
    file_len: usize,
    line: u32,
    column: u32,
) {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let Some(i) = usize::try_from(index).ok().filter(|&i| i < array.len) else {
        index_panic(index, array.len, file, file_len, line, column);
    };
    let stride = array.stride();
    let size = array.info().size;
    // SAFETY: `i` is in bounds; the tail is shifted down within the buffer.
    unsafe {
        std::ptr::copy_nonoverlapping(array.element(i), dst, size);
        std::ptr::copy(
            array.element(i + 1),
            array.element(i),
            (array.len - i - 1) * stride,
        );
    }
    array.len -= 1;
}

/// A new array with clones of elements `start..stop` (clamped).
///
/// # Safety
///
/// `a` must be live and its element type must have clone glue (or be plain data).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_slice(
    a: *mut LoomArray,
    start: i64,
    stop: i64,
) -> *mut LoomArray {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let start = usize::try_from(start).unwrap_or(0).min(array.len);
    let stop = usize::try_from(stop).unwrap_or(0).min(array.len).max(start);
    let out = loom_array_new(array.info);
    // SAFETY: `out` was just created.
    let target = unsafe { get(out) };
    for i in start..stop {
        target.reserve_one();
        // SAFETY: `i` is in bounds of the source; the target has room.
        unsafe { clone_element(array.info(), array.element(i), target.element(target.len)) };
        target.len += 1;
    }
    out
}

/// Clones the element at `src` into `dst` with the descriptor's glue (or a byte copy).
///
/// # Safety
///
/// `src` must hold an element; `dst` must have room for one.
unsafe fn clone_element(info: &TypeInfo, src: *const u8, dst: *mut u8) {
    match info.clone {
        // SAFETY: the glue implements clone for this type.
        Some(clone) => unsafe { clone(src, dst) },
        // SAFETY: plain data is copied bytewise.
        None => unsafe { std::ptr::copy_nonoverlapping(src, dst, info.size) },
    }
}

/// Reverses the elements in place.
///
/// # Safety
///
/// `a` must be live.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_reverse(a: *mut LoomArray) {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let size = array.info().size;
    let mut temp = vec![0u8; size];
    let (mut i, mut j) = (0, array.len);
    while i + 1 < j {
        j -= 1;
        // SAFETY: `i` and `j` are distinct in-bounds indices.
        unsafe {
            std::ptr::copy_nonoverlapping(array.element(i), temp.as_mut_ptr(), size);
            std::ptr::copy_nonoverlapping(array.element(j), array.element(i), size);
            std::ptr::copy_nonoverlapping(temp.as_ptr(), array.element(j), size);
        }
        i += 1;
    }
}

/// The calling convention of a comparison closure: (result, environment, a, b), where the
/// result is an `Ordering` tag (0 less, 1 equal, 2 greater).
pub type CompareFn = unsafe extern "C" fn(*mut u32, *mut u8, *const u8, *const u8);

/// Sorts the elements with a Loom comparison closure; stable.
///
/// # Safety
///
/// `a` must be live and `code`/`env` must be a closure of type `Fn(T, T) -> Ordering`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_sort_by(a: *mut LoomArray, code: CompareFn, env: *mut u8) {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let size = array.info().size;
    let mut order: Vec<usize> = (0..array.len).collect();
    order.sort_by(|&x, &y| {
        let mut tag = 1u32;
        // SAFETY: both indices are in bounds; the closure only reads its arguments.
        unsafe { code(&raw mut tag, env, array.element(x), array.element(y)) };
        match tag {
            0 => std::cmp::Ordering::Less,
            2 => std::cmp::Ordering::Greater,
            _ => std::cmp::Ordering::Equal,
        }
    });
    let mut sorted = vec![0u8; size * array.len];
    for (target, &source) in order.iter().enumerate() {
        // SAFETY: `source` is in bounds and `sorted` has room for every element.
        unsafe {
            std::ptr::copy_nonoverlapping(
                array.element(source),
                sorted.as_mut_ptr().add(target * size),
                size,
            );
        }
    }
    for i in 0..array.len {
        // SAFETY: `i` is in bounds; elements are moved back in their new order.
        unsafe {
            std::ptr::copy_nonoverlapping(sorted.as_ptr().add(i * size), array.element(i), size);
        }
    }
}

/// A clone of the array and its elements.
///
/// # Safety
///
/// `a` must be live.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_clone(a: *mut LoomArray) -> *mut LoomArray {
    // SAFETY: `a` is live.
    let len = unsafe { get(a) }.len;
    // SAFETY: `a` is live.
    unsafe { loom_array_slice(a, 0, i64::try_from(len).unwrap_or(0)) }
}

/// Drops the elements and frees the array.
///
/// # Safety
///
/// `a` must be a live array that is not used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_drop(a: *mut LoomArray) {
    if a.is_null() {
        return;
    }
    // SAFETY: the caller transfers ownership of the handle.
    let array = unsafe { Box::from_raw(a) };
    if let Some(drop_fn) = array.info().drop {
        for i in 0..array.len {
            // SAFETY: each element is initialized and dropped once.
            unsafe { drop_fn(array.element(i)) };
        }
    }
    if !array.data.is_null() {
        // SAFETY: `data` was allocated with this layout.
        unsafe { dealloc(array.data, array.layout(array.capacity)) };
    }
}

/// Whether two arrays have equal elements.
///
/// # Safety
///
/// Both must be live arrays of the same element type with eq glue.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_eq(a: *mut LoomArray, b: *mut LoomArray) -> u8 {
    // SAFETY: both are live; they are only read, so they may be the same array.
    let (left, right) = (unsafe { &*a }, unsafe { &*b });
    if left.len != right.len {
        return 0;
    }
    let Some(eq) = left.info().eq else { return 0 };
    for index in 0..left.len {
        // SAFETY: `index` is in bounds of both.
        if unsafe { eq(left.element(index), right.element(index)) } == 0 {
            return 0;
        }
    }
    1
}

/// Compares two arrays lexicographically.
///
/// # Safety
///
/// Both must be live arrays of the same element type with cmp glue.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_cmp(a: *mut LoomArray, b: *mut LoomArray) -> i8 {
    // SAFETY: both are live; they are only read, so they may be the same array.
    let (left, right) = (unsafe { &*a }, unsafe { &*b });
    let Some(cmp) = left.info().cmp else { return 0 };
    for index in 0..left.len.min(right.len) {
        // SAFETY: `index` is in bounds of both.
        let order = unsafe { cmp(left.element(index), right.element(index)) };
        if order != 0 {
            return order;
        }
    }
    match left.len.cmp(&right.len) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

/// Hashes an array's elements.
///
/// # Safety
///
/// `a` must be live with hash glue for its elements.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_hash(a: *mut LoomArray) -> u64 {
    // SAFETY: `a` is live.
    let array = unsafe { get(a) };
    let mut h = 0xcbf2_9ce4_8422_2325u64 ^ u64::try_from(array.len).unwrap_or(u64::MAX);
    if let Some(hash) = array.info().hash {
        for i in 0..array.len {
            // SAFETY: `i` is in bounds.
            h = (h ^ unsafe { hash(array.element(i)) }).wrapping_mul(0x0100_0000_01b3);
        }
    }
    h
}

/// Appends `[a, b, …]` with each element's debug text.
///
/// # Safety
///
/// `a` and `out` must be live.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn loom_array_debug(a: *mut LoomArray, out: *mut LoomString) {
    // SAFETY: `a` is live; it is only read.
    let array = unsafe { &*a };
    // Each append reborrows `out` briefly: the element glue appends to it too.
    // SAFETY: `out` is live and distinct from the array.
    let push = |text: &str| unsafe { (*out).push_str(text) };
    push("[");
    for index in 0..array.len {
        if index > 0 {
            push(", ");
        }
        if let Some(debug) = array.info().debug {
            // SAFETY: `index` is in bounds; no borrow of `out` is live during the call.
            unsafe { debug(array.element(index), out) };
        }
    }
    push("]");
}
